module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic disc,
    output logic flag,
    output logic err
);

    typedef enum logic [3:0] {
        S0     = 4'd0,
        S1     = 4'd1,
        S2     = 4'd2,
        S3     = 4'd3,
        S4     = 4'd4,
        S5     = 4'd5,
        S6     = 4'd6,
        S7     = 4'd7,
        S_DISC = 4'd8,
        S_FLAG = 4'd9
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always_comb begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (in) next_state = S1;
                else    next_state = S0;
            end
            S1: begin
                if (in) next_state = S2;
                else    next_state = S0;
            end
            S2: begin
                if (in) next_state = S3;
                else    next_state = S0;
            end
            S3: begin
                if (in) next_state = S4;
                else    next_state = S0;
            end
            S4: begin
                if (in) next_state = S5;
                else    next_state = S0;
            end
            S5: begin
                if (in) next_state = S6;
                else    next_state = S_DISC;
            end
            S6: begin
                if (in) next_state = S7;
                else    next_state = S_FLAG;
            end
            S7: begin
                if (in) next_state = S7;
                else    next_state = S0;
            end
            S_DISC: begin
                if (in) next_state = S1;
                else    next_state = S0;
            end
            S_FLAG: begin
                if (in) next_state = S1;
                else    next_state = S0;
            end
            default: begin
                next_state = S0;
            end
        endcase
    end

    // Sequential state update
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    // Moore outputs
    assign disc = (current_state == S_DISC);
    assign flag = (current_state == S_FLAG);
    assign err  = (current_state == S7);

endmodule

